$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.Drawing
$m='D:/Project/Unity/TPSBattle/TPSShoot';$d='D:/Project/Unity/TPSBattle/Builds/MonsterWhitebox-01a1c6ef';$root="$m/Docs/玩法参考设计"
$s=[IO.File]::ReadAllText("$root/怪物复刻统一推进.md");$a=$s.IndexOf('| 配置 | 怪物画面');$b=$s.IndexOf('### 验收方式');$primary=$s.Substring($a,$b-$a)
$names=@{};$j=Get-Content "$m/Assets/Resources/RainImported/RainJournal.json" -Raw|ConvertFrom-Json;foreach($e in $j.entries){if(!$names.ContainsKey($e.key)){$names[$e.key]=$e.name}}
$list=[Collections.Generic.List[object]]::new()
foreach($line in [regex]::Matches($primary,'(?m)^\| `([^`]+)`([^|]*)\|[^\r\n]*')){
 $id=$line.Groups[1].Value;$cols=$line.Value.Split('|');$images=@();foreach($im in [regex]::Matches($cols[2],'!\[[^\]]*\]\(([^)]+)\)')){$p=[IO.Path]::GetFullPath((Join-Path $root ([uri]::UnescapeDataString($im.Groups[1].Value))));if(Test-Path -LiteralPath $p){$images+=$p}}
 $name=$line.Groups[2].Value.Trim();if($names.ContainsKey($id)){$name=$names[$id]};if(!$name){$name=$id}
 $source=if($id-cmatch'^[A-Z_0-9]+$'){'雨中冒险 2'}else{'巨人杀手'};$status=if($id-eq 'bat_loot_sur'){'跳过'}else{'已记录通过'}
 $note=[regex]::Replace(($cols[3..5]-join'；'),'!?\[([^\]]*)\]\([^)]+\)','$1')
 $list.Add([pscustomobject]@{id=$id;name=$name;source=$source;status=$status;scope='主工程已有入口';images=@($images|Select-Object -First 2);note=$note;order=2})
}
foreach($r in $list){
 $idle="$d/Goal2MainRegressionFrames/$($r.id)-idle.png"
 if(Test-Path -LiteralPath $idle){$r.images=@($idle);foreach($phase in @('signature','impact-aimed','impact')){$p="$d/Goal2MainRegressionFrames/$($r.id)-$phase.png";if((Test-Path -LiteralPath $p)-and$r.images.Count-lt2){$r.images+=$p}}}
}
$latest=@{'MINIMUSHROOM_BODY'='Goal2MiniSavedFrames';'BELL_BODY'='Goal2BellIdleCleanFrames';'CLAYBRUISER_BODY'='Goal2ClayTraceFrames';'CLAYGRENADIER_BODY'='Goal2GrenadierFinalFrames';'CHILD_BODY'='Goal2MiniSavedFrames'}
foreach($id in $latest.Keys){$r=$list|Where-Object id -eq $id|Select-Object -First 1;if(!$r){$r=[pscustomobject]@{id=$id;name=$names[$id];source='雨中冒险 2';status='已记录通过';scope='仅隔离工程，未合入主工程';images=@();note='';order=0};$list.Add($r)};$r.images=@();foreach($phase in @('idle','signature','impact-aimed','impact')){$p="$d/$($latest[$id])/$id-$phase.png";if((Test-Path -LiteralPath $p)-and$r.images.Count-lt2){$r.images+=$p}};if($id-in@('MINIMUSHROOM_BODY','BELL_BODY')){$r.scope='主工程已有入口；当前动作修复仅隔离';$r.order=1};$r.note=switch($id){'CLAYBRUISER_BODY'{'近似五连射、15 实伤、声音采样及射击中取消通过。原动画恢复待补修。'}'CLAYGRENADIER_BODY'{'可见抛物线球体、12 实伤、声音采样及飞行中取消通过。原动画恢复待补修。'}'CHILD_BODY'{'实际动作曲线已重建并重载；姿态变化、可见弹体、12 实伤及清理通过。'}'MINIMUSHROOM_BODY'{'实际动作曲线已重建并重载；菌盖／身体变化、弹体、12 实伤及清理通过。'}'BELL_BODY'{'待机名称匹配已修复；弹体、18 实伤及清理通过；原动画恢复待补修。'}}}
$a=$s.IndexOf('### 缺召唤入口');$b=$s.IndexOf('## 1. 运行 Goal');foreach($x in [regex]::Matches($s.Substring($a,$b-$a),'(?m)^\| (巨人杀手|雨中冒险 2) \| `([^`]+)`')){$id=$x.Groups[2].Value;if($id-in@('CLAYBRUISER_BODY','CLAYGRENADIER_BODY','CHILD_BODY')){continue};$name=if($names.ContainsKey($id)){$names[$id]}else{$id};$list.Add([pscustomobject]@{id=$id;name=$name;source=$x.Groups[1].Value;status='待接入／未测';scope='尚无合格验收记录';images=@();note='未测，无合格实机截图，不计通过。';order=4})}
$passed=@($list|Where-Object status -eq '已记录通过');$missing=@($passed|Where-Object {$_.images.Count-eq0});if($list.Count-ne283-or$passed.Count-ne91){throw "Counts $($list.Count) / $($passed.Count)"}
function EncodeHtml([string]$v){[Net.WebUtility]::HtmlEncode($v)}
$enc=[Drawing.Imaging.ImageCodecInfo]::GetImageEncoders()|Where-Object MimeType -eq 'image/jpeg';$par=[Drawing.Imaging.EncoderParameters]::new(1);$par.Param[0]=[Drawing.Imaging.EncoderParameter]::new([Drawing.Imaging.Encoder]::Quality,[long]82)
$body=[Text.StringBuilder]::new();foreach($r in ($list|Sort-Object order,source,id)){$pics='';foreach($p in $r.images){$im=[Drawing.Image]::FromFile($p);$factor=[math]::Min(1.0,[math]::Min(960.0/$im.Width,600.0/$im.Height));$bm=[Drawing.Bitmap]::new([math]::Max(1,[int]($im.Width*$factor)),[math]::Max(1,[int]($im.Height*$factor)));$g=[Drawing.Graphics]::FromImage($bm);$g.DrawImage($im,0,0,$bm.Width,$bm.Height);$ms=[IO.MemoryStream]::new();$bm.Save($ms,$enc,$par);$data=[Convert]::ToBase64String($ms.ToArray());$g.Dispose();$bm.Dispose();$im.Dispose();$ms.Dispose();$time=(Get-Item -LiteralPath $p).LastWriteTime.ToString('yyyy-MM-dd HH:mm');$pics+='<figure><img loading="lazy" src="data:image/jpeg;base64,'+$data+'" onclick="zoom(this.src)" alt="'+(EncodeHtml $r.name)+' 实机截图"><figcaption>记录时间：'+$time+'</figcaption></figure>'};if(!$pics){$pics='<span>未测或非攻击配置，无截图</span>';if($r.status-eq '已记录通过'){$pics='<b class="warn">历史图引用缺失，需补图，不据此完成验收</b>'}};[void]$body.Append('<tr data-status="'+(EncodeHtml $r.status)+'" data-source="'+(EncodeHtml $r.source)+'"><td><b>'+(EncodeHtml $r.name)+'</b><small>'+(EncodeHtml $r.id)+'</small><small>'+(EncodeHtml $r.source)+'</small></td><td>'+(EncodeHtml $r.status)+'<small>'+(EncodeHtml $r.scope)+'</small></td><td class="shots">'+$pics+'</td><td>'+(EncodeHtml $r.note)+'</td></tr>')};$par.Dispose()
$head='<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>怪物实机截图验收汇总</title><style>body{font:15px/1.6 system-ui,"Microsoft YaHei",sans-serif;margin:24px;background:#f3f5f8;color:#182638}h1{font-size:26px}header,.controls{background:white;padding:18px;margin-bottom:14px;border-radius:10px}.warn{color:#a43819}small{display:block;color:#57677a;overflow-wrap:anywhere}.controls{position:sticky;top:0;z-index:2;display:flex;gap:12px;flex-wrap:wrap}input,select{padding:8px;font:inherit}table{border-collapse:collapse;width:100%;background:white}th,td{border:1px solid #d6deea;padding:12px;vertical-align:top}th{background:#e7edf5}td:first-child{min-width:175px}td:nth-child(2){min-width:130px}td:last-child{min-width:210px;max-width:400px}.shots{min-width:315px}figure{display:inline-block;margin:0 8px 8px 0;width:300px}img{width:100%;cursor:zoom-in}figcaption{font-size:11px;color:#64748b}#lightbox{display:none;position:fixed;inset:0;background:#000d;z-index:10;align-items:center;justify-content:center}#lightbox img{width:auto;max-width:96vw;max-height:95vh} @media print{.controls{position:static}tr{break-inside:avoid}}</style><header><h1>怪物实机截图验收汇总</h1><b>Goal 已暂停 · 283 项目录</b><p>已记录通过 <b>91/283</b>（32.16%） · 失败 0 · 待接入／未测 191 · 非攻击跳过 1。</p><p>主工程集成基线仍为 <b>88/283</b>；黏土圣堂武士、黏土药剂师、魔童仅在隔离工程。部分既有入口的后续动作修复也仅在隔离工程。</p><p class="warn">已记录通过是既有白盒行为及截图结论，待老师逐项验收。声音只做 DSP 采样，人工听感未确认；批测仍有 14 条 lilToon 渲染错误，不能视为全部检查通过。</p><p>采用最近保存的实机证据，日期见图下；暂停后没有重新启动全量测试。历史批次的验证范围不完全相同，近似表现和限制见对应行。图片已嵌入文件，点击可放大。</p></header><div class="controls"><input id="q" placeholder="搜索名称或 ID" oninput="filterRows()"><select id="status" onchange="filterRows()"><option>已记录通过</option><option value="">全部状态</option><option>待接入／未测</option><option>跳过</option></select><select id="source" onchange="filterRows()"><option value="">两个项目</option><option>巨人杀手</option><option>雨中冒险 2</option></select><b id="count"></b></div><table><thead><tr><th>怪物／编号</th><th>状态与工程</th><th>最近保存的实机画面</th><th>验证与限制</th></tr></thead><tbody>'
$tail='</tbody></table><div id="lightbox" onclick="this.style.display=''none''"><img id="large" alt="放大截图"></div><script>function zoom(src){document.getElementById("large").src=src;document.getElementById("lightbox").style.display="flex"}document.addEventListener("keydown",e=>{if(e.key==="Escape")document.getElementById("lightbox").style.display="none"});function filterRows(){let q=document.getElementById("q").value.toLowerCase(),s=document.getElementById("status").value,p=document.getElementById("source").value,n=0;document.querySelectorAll("tbody tr").forEach(r=>{let ok=(!s||r.dataset.status===s)&&(!p||r.dataset.source===p)&&(!q||r.textContent.toLowerCase().includes(q));r.hidden=!ok;if(ok)n++});document.getElementById("count").textContent="显示 "+n+" / 283 项"}filterRows();</script></html>'
$out="$d/AcceptanceReports/怪物实机截图验收汇总.html";[IO.File]::WriteAllText($out,$head+$body.ToString()+$tail,[Text.UTF8Encoding]::new($false));$list|ConvertTo-Json -Depth 5|Set-Content "$d/AcceptanceReports/怪物截图来源清单.json" -Encoding utf8
[pscustomobject]@{rows=$list.Count;passed=$passed.Count;missingPassImages=$missing.Count;bytes=(Get-Item $out).Length;output=$out}|ConvertTo-Json